import json

def calculate_phishing_score(email_analysis, url_results, attachment_results, domain_check, sender_info):
    score = 0
    indicators = []

    # URL analysis
    if url_results:
        for url_result in url_results:
            if url_result.get('malicious', 0) > 0:
                score += 30
                indicators.append(f"Malicious URL detected: {url_result.get('url', 'unknown')}")
            if url_result.get('suspicious', 0) > 5:
                score += 15
                indicators.append(f"Suspicious URL: {url_result.get('url', 'unknown')}")

    # Attachment analysis
    if attachment_results:
        for att_result in attachment_results:
            if att_result.get('malicious', 0) > 5:
                score += 50
                indicators.append(f"Malicious attachment: {att_result.get('filename', 'unknown')}")

    # Domain reputation
    if domain_check.get('suspicious'):
        score += 20
        indicators.append('Sender domain lacks proper email authentication')

    # Sender indicators
    for indicator in sender_info.get('suspicious_indicators', []):
        score += 15
        indicators.append(indicator)

    # Determine verdict
    if score >= 70:
        verdict = 'malicious'
        action = 'block_and_remediate'
    elif score >= 40:
        verdict = 'suspicious'
        action = 'quarantine_and_investigate'
    else:
        verdict = 'clean'
        action = 'release'

    return {
        'score': score,
        'verdict': verdict,
        'recommended_action': action,
        'indicators': indicators
    }

